const YEAR_NOW = new Date().getFullYear();
const classes = ['Genel İdare Hizmetleri','Teknik Hizmetler','Sağlık Hizmetleri ve Yardımcı Sağlık Hizmetleri','Eğitim ve Öğretim Hizmetleri','Avukatlık Hizmetleri','Din Hizmetleri','Emniyet Hizmetleri','Yardımcı Hizmetler','Diğer'];
const pages = {overview:'Genel Bakış',institutions:'Kurumlar',staff:'Personel Havuzu',tariffs:'Yıllık Tarifeler',payments:'Ödeme Dönemi'};
let db = {institutions:[],staff:[],tariffs:[],years:[],batches:[]};
let page = 'overview', activeYear = YEAR_NOW, selectedInstitution = '', payMode = 'Nakdi';
const $ = (s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = () => crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const money = n => new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(Number(n)||0);
const dateText = s => s ? new Date(s+'T12:00:00').toLocaleDateString('tr-TR') : '—';
async function load(){try{const r=await fetch('/api/data');db=await r.json();if(!db.years.some(x=>Number(x.year)===YEAR_NOW)){db.years.push({year:YEAR_NOW,incomeTax:'',stampTax:''});await save()}}catch(e){showToast('Yerel veri sunucusuna ulaşılamadı. Baslat.bat dosyasını yeniden çalıştırın.')}}
async function save(){const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(db)});if(!r.ok)throw new Error('Kayıt başarısız');}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
function showToast(s){setTimeout(()=>toast(s),50)}
function setPage(p){page=p;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#pageTitle').textContent=pages[p];$('#yearBadge').textContent=`YIL · ${activeYear}`;render()}
function nav(){ $$('.nav').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page))); }
const instName = x => db.institutions.find(i=>i.id===x)?.name||'Kurum seçilmemiş';
function render(){const root=$('#page'); if(page==='overview')root.innerHTML=overview();if(page==='institutions')root.innerHTML=institutionsPage();if(page==='staff')root.innerHTML=staffPage();if(page==='tariffs')root.innerHTML=tariffsPage();if(page==='payments')root.innerHTML=paymentsPage();bindPage();}
function overview(){let count=db.staff.filter(s=>s.active!==false).length, activeInst=db.institutions.length, t=db.tariffs.filter(x=>Number(x.year)===Number(activeYear)).length, batches=db.batches.filter(x=>Number(x.year)===Number(activeYear));let total=batches.reduce((a,b)=>a+(b.totalNet||0),0);return `<div class="hero"><h2>Giyecek yardımı işlemleriniz tek yerde.</h2><p>Personel havuzunu yönetin, ilgili yılın tarifesini tanımlayın ve kurum seçerek ayni/nakdi ödeme listelerini hazırlayın.</p></div><div class="stats"><div class="stat"><div class="label">KAYITLI AKTİF PERSONEL</div><strong>${count}</strong><em>Tüm bağlı kurumlar</em></div><div class="stat"><div class="label">KAYITLI KURUM</div><strong>${activeInst}</strong><em>İlçe müdürlüğü ve okullar</em></div><div class="stat"><div class="label">${activeYear} TARİFE KALEMİ</div><strong>${t}</strong><em>Unvan ve giyecek tanımları</em></div><div class="stat"><div class="label">${activeYear} HAZIRLANAN ÖDEME</div><strong>${money(total)}</strong><em>${batches.length} ödeme listesi</em></div></div><div class="grid2"><div class="card"><div class="cardhead"><div><h2>Hızlı başlangıç</h2><p>İlk kullanımda şu sırayı izleyin</p></div></div><div class="tablewrap"><table><thead><tr><th>Adım</th><th>İşlem</th><th>Durum</th></tr></thead><tbody><tr><td>01</td><td>Kurumları tanımlayın</td><td>${db.institutions.length?'<span class="badge">Hazır</span>':'<span class="badge amber">Bekliyor</span>'}</td></tr><tr><td>02</td><td>Personel havuzunu oluşturun</td><td>${count?'<span class="badge">Hazır</span>':'<span class="badge amber">Bekliyor</span>'}</td></tr><tr><td>03</td><td>${activeYear} tarife kalemlerini girin</td><td>${t?'<span class="badge">Hazır</span>':'<span class="badge amber">Bekliyor</span>'}</td></tr><tr><td>04</td><td>Kurum ve ödeme dönemini seçin</td><td>${batches.length?'<span class="badge">Hazır</span>':'<span class="badge amber">Bekliyor</span>'}</td></tr></tbody></table></div></div><div class="card"><div class="cardhead"><div><h2>Son hazırlanan listeler</h2><p>Ödeme dönemi kayıtları</p></div><button class="btn secondary" data-goto="payments">Tümünü gör</button></div>${batches.length?tableBatches(batches.slice().reverse().slice(0,4)):'<div class="empty">Henüz ödeme listesi oluşturulmadı.</div>'}</div></div><div class="callout">Yıllık fiyat ve kullanım süreleri genelgeye göre değişebilir. Tarifeyi her yıl gözden geçirin; hesaplama öncesi doğru yılın fiyatlarını ve uygulanacak vergi oranlarını girin.</div>`}
function institutionsPage(){return `<div class="card"><div class="cardhead"><div><h2>Kurum listesi</h2><p>Müdürlük ve bağlı okul/kurum kayıtları</p></div><button class="btn" data-action="add-inst">+ Kurum ekle</button></div>${db.institutions.length?`<div class="tablewrap"><table><thead><tr><th>Kurum adı</th><th>Kurum türü</th><th>Personel</th><th></th></tr></thead><tbody>${db.institutions.map(i=>`<tr><td><b>${esc(i.name)}</b></td><td>${esc(i.type||'—')}</td><td>${db.staff.filter(s=>s.institutionId===i.id&&s.active!==false).length}</td><td><button class="smallbtn" data-action="del-inst" data-id="${esc(i.id)}">Sil</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Henüz kurum eklenmemiş. İlk kurumunuzu ekleyerek başlayın.</div>'}</div>`}
function staffPage(){let list=db.staff.filter(s=>!selectedInstitution||s.institutionId===selectedInstitution);return `<div class="card"><div class="cardhead"><div><h2>Personel kayıtları</h2><p>Personel havuzu, giyim yardımı hesaplamalarında kullanılacak temel bilgileri tutar.</p></div><div class="actions"><button class="btn secondary" data-action="import-staff">CSV içe aktar</button><button class="btn" data-action="add-staff">+ Personel ekle</button><input type="file" id="csvFile" accept=".csv,text/csv" hidden></div></div><div class="toolbar"><select class="fieldinput" id="filterInstitution"><option value="">Tüm kurumlar</option>${db.institutions.map(i=>`<option value="${esc(i.id)}" ${selectedInstitution===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select><input class="fieldinput search" id="staffSearch" placeholder="Ad, unvan veya kurum ara..."></div>${list.length?`<div class="tablewrap"><table id="staffTable"><thead><tr><th>Ad soyad</th><th>Kurum</th><th>Unvan</th><th>Hizmet sınıfı</th><th>Durum</th><th></th></tr></thead><tbody>${list.map(s=>`<tr data-search="${esc((s.name+' '+s.title+' '+instName(s.institutionId)).toLocaleLowerCase('tr'))}"><td><b>${esc(s.name)}</b></td><td>${esc(instName(s.institutionId))}</td><td>${esc(s.title)}</td><td>${esc(s.serviceClass)}</td><td>${s.active===false?'<span class="badge red">Pasif</span>':'<span class="badge">Aktif</span>'}</td><td><button class="smallbtn" data-action="del-staff" data-id="${esc(s.id)}">Sil</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Bu ölçütlerde personel yok. CSV ile içe aktarabilir veya elle ekleyebilirsiniz.</div>'}<div class="callout green">CSV başlıkları: <b>Ad Soyad, Kurum, Unvan, Hizmet Sınıfı</b>. Dosyanız UTF-8 veya Türkçe Windows kodlamasında olabilir. T.C. kimlik numarası uygulama tarafından istenmez.</div></div>`}
function tariffsPage(){let yearRow=db.years.find(x=>Number(x.year)===Number(activeYear))||{year:activeYear,incomeTax:'',stampTax:''}, rows=db.tariffs.filter(t=>Number(t.year)===Number(activeYear));return `<div class="toolbar"><div class="field" style="margin:0"><label>Tarife yılı</label><select id="yearSelect">${yearOptions()}</select></div><button class="btn" data-action="add-tariff">+ Tarife kalemi ekle</button><button class="btn secondary right" data-action="backup">Yedek al</button><button class="btn secondary" data-action="restore">Yedek yükle</button><input type="file" id="backupFile" accept=".json,application/json" hidden></div><div class="card"><div class="cardhead"><div><h2>${activeYear} yılı uygulama ayarları</h2><p>Nakdi ödeme hesaplarında kullanılacak oranlar ve genelge kaydı</p></div><button class="btn light" data-action="save-year">Ayarları kaydet</button></div><div class="formgrid"><div class="field"><label>Gelir vergisi kesinti oranı (%)</label><input type="number" id="incomeTax" min="0" max="100" step="0.01" value="${esc(yearRow.incomeTax)}" placeholder="Uygulanacak oranı girin"></div><div class="field"><label>Damga vergisi kesinti oranı (%)</label><input type="number" id="stampTax" min="0" max="100" step="0.001" value="${esc(yearRow.stampTax)}" placeholder="Uygulanacak oranı girin"></div><div class="field wide"><label>Genelge / kaynak notu</label><input id="yearSource" value="${esc(yearRow.source||'')}" placeholder="Örn. HMB 2026/4 Sıra No’lu Genelge, 08.01.2026"></div></div><p class="hint">Bu oranlar için uygulamanızda esas aldığınız bordro/mevzuat oranlarını girin. Uygulama, girilen oranları brüt nakdi giyecek tutarına uygular; oranı kendiliğinden tahmin etmez.</p></div><div class="card"><div class="cardhead"><div><h2>Yardım tarifesi</h2><p>Unvan ve hizmet sınıfı bazında giyecek kalemleri, brüt tutar ve tekrar süresi</p></div><span class="badge">${rows.length} kalem</span></div>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Unvan</th><th>Hizmet sınıfı</th><th>Giyecek</th><th>Yardım türü</th><th>Birim tutarı</th><th>Kullanım süresi</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.serviceClass||'Tüm sınıflar')}</td><td><b>${esc(t.item)}</b></td><td><span class="badge ${t.mode==='Ayni'?'amber':''}">${esc(t.mode)}</span></td><td class="money">${money(t.amount)}</td><td>${t.years} yıl</td><td><button class="smallbtn" data-action="del-tariff" data-id="${esc(t.id)}">Sil</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Bu yıl için tarife yok. Genelgedeki uygun kalemleri ekleyin.</div>'}</div>`}
function yearOptions(){let ys=[...new Set([...db.years.map(x=>Number(x.year)),...db.tariffs.map(x=>Number(x.year)),YEAR_NOW,activeYear])].sort((a,b)=>b-a);return ys.map(y=>`<option value="${y}" ${Number(activeYear)===y?'selected':''}>${y}</option>`).join('')}
function paymentsPage(){let insts=db.institutions, list=db.batches.filter(b=>Number(b.year)===Number(activeYear));return `<div class="card"><div class="cardhead"><div><h2>Yeni ödeme dönemi hazırla</h2><p>Yıl ve kurum seçin; program tarife ve önceki ödeme geçmişine göre ödenecek personeli çıkarır.</p></div></div><div class="toolbar"><div class="field" style="margin:0"><label>Yardım yılı</label><select id="paymentYear">${yearOptions()}</select></div><div class="field" style="margin:0;min-width:260px"><label>Kurum</label><select id="paymentInstitution"><option value="">Kurum seçin</option>${insts.map(i=>`<option value="${esc(i.id)}" ${selectedInstitution===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div><button class="btn" data-action="calculate">Ödemeye uygunları hesapla</button></div><div class="hint">Aynı personel ve giyecek kalemi için önceki ödeme, tarifedeki kullanım süresi dolmadan yeniden önerilmez. Hazırlanan listenin resmî ödeme öncesinde kontrol edilmesi gerekir.</div></div><div id="calcResult"></div><div class="card"><div class="cardhead"><div><h2>${activeYear} kayıtlı ödeme listeleri</h2><p>Hazırlanmış nakdi ve ayni listeler</p></div></div>${list.length?tableBatches(list.slice().reverse()):'<div class="empty">Seçilen yıl için liste yok.</div>'}</div>`}
function tableBatches(rows){return `<div class="tablewrap"><table><thead><tr><th>Tarih</th><th>Kurum</th><th>Yıl</th><th>Personel</th><th>Net toplam</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr><td>${dateText(b.date)}</td><td>${esc(instName(b.institutionId))}</td><td>${b.year}</td><td>${b.details.length}</td><td class="money"><b>${money(b.totalNet)}</b></td><td><button class="smallbtn" data-action="view-batch" data-id="${esc(b.id)}">Görüntüle</button></td></tr>`).join('')}</tbody></table></div>`}
function modal(title,sub,content,submitLabel='Kaydet'){const d=$('#modal');$('#modalBody').innerHTML=`<h2>${title}</h2><p class="dialog-sub">${sub}</p>${content}<div class="dialog-actions"><button class="btn secondary" value="cancel">Vazgeç</button><button class="btn" id="modalSave" value="default">${submitLabel}</button></div>`;d.showModal();return d}
function field(label,name,placeholder='',type='text',value=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" required></div>`}
function bindPage(){const y=$('#yearSelect');if(y)y.onchange=()=>{activeYear=Number(y.value);$('#yearBadge').textContent=`YIL · ${activeYear}`;render()};const py=$('#paymentYear');if(py)py.onchange=()=>{activeYear=Number(py.value);$('#yearBadge').textContent=`YIL · ${activeYear}`;render()};const fi=$('#filterInstitution');if(fi)fi.onchange=()=>{selectedInstitution=fi.value;render()};const search=$('#staffSearch');if(search)search.oninput=()=>$$('#staffTable tbody tr').forEach(r=>r.hidden=!r.dataset.search.includes(search.value.toLocaleLowerCase('tr')));$$('[data-goto]').forEach(b=>b.onclick=()=>setPage(b.dataset.goto));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));}
async function action(a,key){if(a==='add-inst')return addInst();if(a==='add-staff')return addStaff();if(a==='add-tariff')return addTariff();if(a==='del-inst')return deleteRow('institutions',key,'Kurumu silmek istediğinize emin misiniz?');if(a==='del-staff')return deleteRow('staff',key,'Personel kaydını silmek istediğinize emin misiniz?');if(a==='del-tariff')return deleteRow('tariffs',key,'Tarife kalemini silmek istediğinize emin misiniz?');if(a==='save-year')return saveYear();if(a==='calculate')return calculate();if(a==='view-batch')return viewBatch(key);if(a==='backup')return backup();if(a==='restore')return $('#backupFile').click();if(a==='import-staff')return $('#csvFile').click();}
function addInst(){let d=modal('Kurum ekle','Müdürlük veya bağlı kurum kaydı oluşturun.',`<div class="formgrid">${field('Kurum adı','name','Örn. Atatürk Ortaokulu')}<div class="field"><label>Kurum türü</label><select name="type"><option>İlçe Millî Eğitim Müdürlüğü</option><option>Okul</option><option>Diğer kurum</option></select></div></div>`);$('#modalSave').onclick=async e=>{e.preventDefault();let f=new FormData($('#modalForm'));let name=f.get('name').trim();if(!name)return;db.institutions.push({id:id(),name,type:f.get('type')});await save();d.close();render();toast('Kurum eklendi.')}}
function addStaff(){if(!db.institutions.length){toast('Önce kurum ekleyin.');return setPage('institutions')}let d=modal('Personel ekle','Personel havuzuna yeni kayıt ekleyin.',`<div class="formgrid">${field('Ad soyad','name','Ad Soyad')}<div class="field"><label>Kurum</label><select name="institutionId" required>${db.institutions.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select></div>${field('Kadro unvanı','title','Örn. Hizmetli')}<div class="field"><label>Hizmet sınıfı</label><select name="serviceClass">${classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Durum</label><select name="active"><option value="true">Aktif</option><option value="false">Pasif</option></select></div></div>`);$('#modalSave').onclick=async e=>{e.preventDefault();let f=new FormData($('#modalForm'));if(!f.get('name').trim()||!f.get('title').trim())return;db.staff.push({id:id(),name:f.get('name').trim(),institutionId:f.get('institutionId'),title:f.get('title').trim(),serviceClass:f.get('serviceClass'),active:f.get('active')==='true'});await save();d.close();render();toast('Personel eklendi.')}}
function addTariff(){let d=modal('Tarife kalemi ekle',`${activeYear} yılı için genelgedeki bir giyecek/yardım hakkını tanımlayın.`, `<div class="formgrid">${field('Kadro unvanı','title','Örn. Şoför')}<div class="field"><label>Hizmet sınıfı (boş = tümü)</label><select name="serviceClass"><option value="">Tüm hizmet sınıfları</option>${classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div>${field('Giyecek kalemi','item','Örn. Ayakkabı')}<div class="field"><label>Yardım türü</label><select name="mode"><option>Nakdi</option><option>Ayni</option></select></div>${field('Birim tutarı (TL)','amount','Örn. 320,98','number')}<div class="field"><label>Kullanım süresi (yıl)</label><input name="years" type="number" min="1" step="1" value="1" required></div></div><p class="hint">Nakdi yardım için genelgedeki azami birim fiyatı, ayni yardım için kurumunuzun uygulayacağı fiyatı girin.</p>`);$('#modalSave').onclick=async e=>{e.preventDefault();let f=new FormData($('#modalForm')), amount=Number(f.get('amount')), years=Number(f.get('years'));if(!f.get('title').trim()||!f.get('item').trim()||amount<0||years<1)return;db.tariffs.push({id:id(),year:activeYear,title:f.get('title').trim(),serviceClass:f.get('serviceClass'),item:f.get('item').trim(),mode:f.get('mode'),amount,years});await save();d.close();render();toast('Tarife kalemi eklendi.')}}
function deleteRow(collection,key,msg){if(!confirm(msg))return;db[collection]=db[collection].filter(x=>x.id!==key);save().then(()=>{render();toast('Kayıt silindi.')})}
async function saveYear(){let y=db.years.find(x=>Number(x.year)===Number(activeYear))||{year:activeYear};y.incomeTax=$('#incomeTax').value;y.stampTax=$('#stampTax').value;y.source=$('#yearSource').value; if(!db.years.some(x=>Number(x.year)===Number(activeYear)))db.years.push(y);else db.years=db.years.map(x=>Number(x.year)===Number(activeYear)?y:x);await save();toast('Yıl ayarları kaydedildi.')}
function paymentHistory(personId,item){return db.batches.flatMap(b=>b.details||[]).filter(d=>d.staffId===personId&&d.item===item&&d.paid!==false).map(d=>Number(d.year)).sort((a,b)=>b-a)}
function calculate(){const yr=Number($('#paymentYear').value), inst=$('#paymentInstitution').value;if(!inst){toast('Kurum seçin.');return}activeYear=yr;selectedInstitution=inst;const rows=db.tariffs.filter(t=>Number(t.year)===yr);if(!rows.length){$('#calcResult').innerHTML='<div class="callout">Bu yıl için tarife kalemi girilmemiş. Önce Yıllık Tarifeler sayfasını tamamlayın.</div>';return}let staff=db.staff.filter(s=>s.institutionId===inst&&s.active!==false), due=[];for(const s of staff){for(const t of rows){if(s.title.trim().toLocaleLowerCase('tr')!==t.title.trim().toLocaleLowerCase('tr'))continue;if(t.serviceClass&&s.serviceClass!==t.serviceClass)continue;const hist=paymentHistory(s.id,t.item);if(hist.length&&hist[0]+Number(t.years)>yr)continue;if(db.batches.some(b=>Number(b.year)===yr&&(b.details||[]).some(d=>d.staffId===s.id&&d.item===t.item)))continue;let gross=Number(t.amount), income=gross*(Number((db.years.find(x=>Number(x.year)===yr)||{}).incomeTax)||0)/100, stamp=gross*(Number((db.years.find(x=>Number(x.year)===yr)||{}).stampTax)||0)/100;due.push({staffId:s.id,staffName:s.name,title:s.title,serviceClass:s.serviceClass,item:t.item,mode:t.mode,amount:gross,years:Number(t.years),year:yr,incomeTax:income,stampTax:stamp,net:gross-income-stamp})}}let cash=due.filter(d=>d.mode==='Nakdi'), ayni=due.filter(d=>d.mode==='Ayni'), totals=arr=>arr.reduce((a,d)=>a+d.amount,0);window.pendingBatch={yr,inst,due};$('#calcResult').innerHTML=`<div class="stats"><div class="stat"><div class="label">UYGUN PERSONEL</div><strong>${new Set(due.map(d=>d.staffId)).size}</strong></div><div class="stat"><div class="label">NAKDİ TOPLAM</div><strong>${money(totals(cash))}</strong><em>${cash.length} giyecek kalemi</em></div><div class="stat"><div class="label">NAKDİ NET TAHMİNİ</div><strong>${money(cash.reduce((a,d)=>a+d.net,0))}</strong><em>Girilen kesinti oranlarına göre</em></div><div class="stat"><div class="label">AYNİ TOPLAM DEĞERİ</div><strong>${money(totals(ayni))}</strong><em>${ayni.length} giyecek kalemi</em></div></div>${cash.length&&(!String((db.years.find(x=>Number(x.year)===yr)||{}).incomeTax).trim()||!String((db.years.find(x=>Number(x.year)===yr)||{}).stampTax).trim())?'<div class="callout">Nakdi net tutar hesabı için yıllık tarife ayarlarındaki vergi oranlarını tamamlayın. Oranlar boşken brüt tutar ile net tutar aynı görünür.</div>':''}<div class="card"><div class="cardhead"><div><h2>Hesaplama sonucu · ${esc(instName(inst))}</h2><p>${yr} yılı için kullanım süresi ve önceki ödeme geçmişi uygulanmıştır.</p></div><button class="btn" data-action="save-batch" id="saveBatch">Bu listeyi kaydet</button></div><div class="tabs"><button class="tab active" data-mode="Nakdi">Nakdi · ${cash.length}</button><button class="tab" data-mode="Ayni">Ayni · ${ayni.length}</button></div><div id="modeTable">${tableDue(cash)}</div></div>`;$$('#calcResult [data-mode]').forEach(b=>b.onclick=()=>{payMode=b.dataset.mode;$$('#calcResult [data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#modeTable').innerHTML=tableDue(payMode==='Nakdi'?cash:ayni)});$('#saveBatch').onclick=saveBatch}
function tableDue(rows){if(!rows.length)return '<div class="empty">Bu yardım türünde ödeme önerilecek giyecek kalemi bulunmuyor.</div>';return `<div class="tablewrap"><table><thead><tr><th>Ad soyad</th><th>Unvan</th><th>Giyecek</th><th>Brüt</th><th>Gelir vergisi</th><th>Damga vergisi</th><th>Net</th><th>Tekrar</th></tr></thead><tbody>${rows.map(d=>`<tr><td>${esc(d.staffName)}</td><td>${esc(d.title)}</td><td><b>${esc(d.item)}</b></td><td class="money">${money(d.amount)}</td><td class="money">${money(d.incomeTax)}</td><td class="money">${money(d.stampTax)}</td><td class="money"><b>${money(d.net)}</b></td><td>${d.years} yıl</td></tr>`).join('')}</tbody></table></div>`}
async function saveBatch(){let p=window.pendingBatch;if(!p||!p.due.length){toast('Kaydedilecek ödeme kalemi yok.');return}if(db.batches.some(b=>Number(b.year)===p.yr&&b.institutionId===p.inst)){toast('Bu kurum ve yıl için kayıtlı bir liste zaten var.');return}let details=p.due.map(d=>({...d,paid:true}));let batch={id:id(),year:p.yr,institutionId:p.inst,date:new Date().toISOString().slice(0,10),details,totalGross:details.filter(d=>d.mode==='Nakdi').reduce((a,d)=>a+d.amount,0),totalNet:details.filter(d=>d.mode==='Nakdi').reduce((a,d)=>a+d.net,0),totalAyni:details.filter(d=>d.mode==='Ayni').reduce((a,d)=>a+d.amount,0)};db.batches.push(batch);await save();toast('Ödeme listesi kaydedildi.');render();$('#calcResult').innerHTML=`<div class="callout green">Liste kaydedildi. Nakdi ve ayni çıktıları aşağıdaki listeden görüntüleyebilir, yazdırabilir veya CSV alabilirsiniz.</div><button class="btn" data-action="view-batch" data-id="${batch.id}">Kaydedilen listeyi görüntüle</button>`;bindPage()}
function viewBatch(key){let b=db.batches.find(x=>x.id===key);if(!b)return;const d=modal(`Ödeme listesi · ${b.year}`,`${instName(b.institutionId)} · ${dateText(b.date)}`,`<div class="actions no-print"><button class="btn secondary" id="exportCash">Nakdi CSV indir</button><button class="btn secondary" id="exportAyni">Ayni CSV indir</button><button class="btn light" id="printReport">Yazdır / PDF</button></div><div class="reporthead"><h2>GİYECEK YARDIMI DAĞITIM LİSTESİ</h2><p>${esc(instName(b.institutionId))} · ${b.year} · ${dateText(b.date)}</p></div><div class="tabs"><button class="tab active" data-mode="Nakdi">Nakdi</button><button class="tab" data-mode="Ayni">Ayni</button></div><div id="batchTable">${tableDue(b.details.filter(x=>x.mode==='Nakdi'))}</div><div class="callout">Bu uygulama yardımcı hesaplama ve liste hazırlama aracıdır. Nihai ödeme ve resmî belge kontrolü ilgili harcama yetkilisi/muhasebe sürecinde yapılmalıdır.</div>`,'Kapat');const show=m=>$('#batchTable').innerHTML=tableDue(b.details.filter(x=>x.mode===m));$$('dialog [data-mode]').forEach(x=>x.onclick=()=>{$$('dialog [data-mode]').forEach(y=>y.classList.toggle('active',x===y));show(x.dataset.mode)});$('#exportCash').onclick=()=>downloadCsv(b,'Nakdi');$('#exportAyni').onclick=()=>downloadCsv(b,'Ayni');$('#printReport').onclick=()=>window.print()}
function downloadCsv(batch,mode){let rows=batch.details.filter(d=>d.mode===mode);let head=mode==='Nakdi'?['Yardım Yılı','Kurum','Ad Soyad','Kadro Unvanı','Hizmet Sınıfı','Giyecek Kalemi','Brüt Tutar (TL)','Gelir Vergisi Kesintisi (TL)','Damga Vergisi Kesintisi (TL)','Net Tutar (TL)','Kullanım Süresi (Yıl)']:['Yardım Yılı','Kurum','Ad Soyad','Kadro Unvanı','Hizmet Sınıfı','Giyecek Kalemi','Birim Değeri (TL)','Kullanım Süresi (Yıl)'];let data=rows.map(d=>mode==='Nakdi'?[d.year,instName(batch.institutionId),d.staffName,d.title,d.serviceClass,d.item,d.amount.toFixed(2),d.incomeTax.toFixed(2),d.stampTax.toFixed(2),d.net.toFixed(2),d.years]:[d.year,instName(batch.institutionId),d.staffName,d.title,d.serviceClass,d.item,d.amount.toFixed(2),d.years]);let csv='\ufeff'+[head,...data].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`Giyecek_${mode}_${batch.year}.csv`;a.click();URL.revokeObjectURL(a.href)}
function backup(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download=`Giyim_Yardimi_Yedek_${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Yedek dosyası indirildi.')}
function csvParse(text){let rows=[],row=[],cell='',q=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'&&q&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')q=!q;else if((c===';'||c===',')&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function norm(s){return String(s||'').trim().toLocaleLowerCase('tr').replace(/[ıİ]/g,'i').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
async function importCsv(file){let buf=await file.arrayBuffer(),text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(buf)}catch{text=new TextDecoder('windows-1254').decode(buf)}let rows=csvParse(text);if(rows.length<2){toast('CSV dosyasında veri satırı yok.');return}let headers=rows[0].map(norm),find=(...names)=>names.map(x=>headers.indexOf(norm(x))).find(i=>i>=0),ix={name:find('Ad Soyad','Adı Soyadı','Ad Soyadi'),inst:find('Kurum','Okul','Kurum Adı'),title:find('Unvan','Kadro Unvanı','Ünvan'),cls:find('Hizmet Sınıfı','Sınıf')};if(Object.values(ix).some(x=>x===undefined)){toast('CSV başlıklarını kontrol edin: Ad Soyad, Kurum, Unvan, Hizmet Sınıfı');return}let n=0,missing=[];for(let r of rows.slice(1)){let name=(r[ix.name]||'').trim(),institution=(r[ix.inst]||'').trim(),title=(r[ix.title]||'').trim(),serviceClass=(r[ix.cls]||'').trim();if(!name||!institution||!title)continue;let ins=db.institutions.find(x=>norm(x.name)===norm(institution));if(!ins){ins={id:id(),name:institution,type:'Okul'};db.institutions.push(ins)}if(db.staff.some(s=>norm(s.name)===norm(name)&&s.institutionId===ins.id&&norm(s.title)===norm(title)))continue;db.staff.push({id:id(),name,institutionId:ins.id,title,serviceClass:classes.includes(serviceClass)?serviceClass:'Diğer',active:true});n++}await save();render();toast(`${n} personel kaydı içe aktarıldı.`)}
async function bindGlobal(){document.addEventListener('click',e=>{if(e.target.id==='csvFile')return});$('#csvFile').onchange=async e=>{let f=e.target.files[0];if(f)await importCsv(f);e.target.value=''};$('#backupFile').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(!Array.isArray(x.staff)||!Array.isArray(x.institutions)||!Array.isArray(x.tariffs)||!Array.isArray(x.batches))throw 0;if(!confirm('Yedek yüklenecek ve mevcut kayıtların üzerine yazılacak. Devam edilsin mi?'))return;db=x;await save();render();toast('Yedek yüklendi.')}catch{toast('Yedek dosyası okunamadı.')}e.target.value=''};$('#nav').addEventListener('click',()=>{});document.addEventListener('click',e=>{if(e.target.closest('[data-action="save-batch"]'))saveBatch()})}
async function init(){nav();await load();await bindGlobal();render();}
// Enhancements loaded with the first MVP: keep file controls wired after page switches.
function render(){const root=$('#page');if(page==='overview')root.innerHTML=overview();if(page==='institutions')root.innerHTML=institutionsPage();if(page==='staff')root.innerHTML=staffPage();if(page==='tariffs'){root.innerHTML=tariffsPage();const bar=$('.toolbar',root);if(bar){bar.insertAdjacentHTML('beforeend','<button class="btn secondary" data-action="import-tariffs">Tarifeyi CSV\'den al</button><button class="btn secondary" data-action="tariff-template">CSV şablonu</button><input type="file" id="tariffFile" accept=".csv,text/csv" hidden>')}}if(page==='payments')root.innerHTML=paymentsPage();bindPage()}
function bindPage(){const y=$('#yearSelect');if(y)y.onchange=()=>{activeYear=Number(y.value);$('#yearBadge').textContent=`YIL · ${activeYear}`;render()};const py=$('#paymentYear');if(py)py.onchange=()=>{activeYear=Number(py.value);$('#yearBadge').textContent=`YIL · ${activeYear}`;render()};const fi=$('#filterInstitution');if(fi)fi.onchange=()=>{selectedInstitution=fi.value;render()};const search=$('#staffSearch');if(search)search.oninput=()=>$$('#staffTable tbody tr').forEach(r=>r.hidden=!r.dataset.search.includes(search.value.toLocaleLowerCase('tr')));$$('[data-goto]').forEach(b=>b.onclick=()=>setPage(b.dataset.goto));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id))}
async function action(a,key){if(a==='import-tariffs')return $('#tariffFile')?.click();if(a==='tariff-template')return tariffTemplate();if(a==='add-inst')return addInst();if(a==='add-staff')return addStaff();if(a==='add-tariff')return addTariff();if(a==='del-inst')return deleteRow('institutions',key,'Kurumu silmek istediğinize emin misiniz?');if(a==='del-staff')return deleteRow('staff',key,'Personel kaydını silmek istediğinize emin misiniz?');if(a==='del-tariff')return deleteRow('tariffs',key,'Tarife kalemini silmek istediğinize emin misiniz?');if(a==='save-year')return saveYear();if(a==='calculate')return calculate();if(a==='view-batch')return viewBatch(key);if(a==='backup')return backup();if(a==='restore')return $('#backupFile')?.click();if(a==='import-staff')return $('#csvFile')?.click()}
function csvText(file){return file.arrayBuffer().then(buf=>{try{return new TextDecoder('utf-8',{fatal:true}).decode(buf)}catch{return new TextDecoder('windows-1254').decode(buf)}})}
async function importTariffs(file){const rows=csvParse(await csvText(file));if(rows.length<2){toast('CSV dosyasında tarife satırı yok.');return}const hs=rows[0].map(norm),find=(...n)=>n.map(x=>hs.indexOf(norm(x))).find(i=>i>=0),ix={year:find('Yıl','Yardım Yılı'),title:find('Unvan','Kadro Unvanı'),cls:find('Hizmet Sınıfı'),item:find('Giyecek Kalemi','Giyecek'),mode:find('Yardım Türü','Tür'),amount:find('Birim Tutarı TL','Birim Tutarı'),years:find('Kullanım Süresi Yıl','Kullanım Süresi')};if(Object.values(ix).some(x=>x===undefined)){toast('Tarife CSV başlıkları uygun değil. CSV şablonunu indirin.');return}let added=0;for(const r of rows.slice(1)){const title=(r[ix.title]||'').trim(),item=(r[ix.item]||'').trim(),mode=(r[ix.mode]||'').trim(),amount=Number(String(r[ix.amount]||'').replace(',','.')),year=Number(r[ix.year]||activeYear),years=Number(r[ix.years]||1),serviceClass=(r[ix.cls]||'').trim();if(!title||!item||!['Nakdi','Ayni'].includes(mode)||!Number.isFinite(amount)||amount<0||!Number.isFinite(year)||years<1)continue;db.tariffs.push({id:id(),year,title,serviceClass,item,mode,amount,years});added++}await save();render();toast(`${added} tarife kalemi içe aktarıldı.`)}
function tariffTemplate(){const csv='\ufeffYıl;Unvan;Hizmet Sınıfı;Giyecek Kalemi;Yardım Türü;Birim Tutarı TL;Kullanım Süresi Yıl\r\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Giyecek_Tarife_Sablonu.csv';a.click();URL.revokeObjectURL(a.href)}
async function restoreBackup(file){try{const x=JSON.parse(await file.text());if(!Array.isArray(x.staff)||!Array.isArray(x.institutions)||!Array.isArray(x.tariffs)||!Array.isArray(x.batches)||!Array.isArray(x.years))throw 0;if(!confirm('Yedek yüklenecek ve mevcut kayıtların üzerine yazılacak. Devam edilsin mi?'))return;db=x;await save();render();toast('Yedek yüklendi.')}catch{toast('Yedek dosyası okunamadı.')}}
async function saveBatch(){const p=window.pendingBatch;if(!p||!p.due.length){toast('Kaydedilecek ödeme kalemi yok.');return}if(p.due.some(d=>d.mode==='Nakdi')){const y=db.years.find(x=>Number(x.year)===p.yr);if(!y||String(y.incomeTax).trim()===''||String(y.stampTax).trim()===''){toast('Önce yıllık gelir ve damga vergisi oranlarını girip kaydedin.');return}}if(db.batches.some(b=>Number(b.year)===p.yr&&b.institutionId===p.inst)){toast('Bu kurum ve yıl için kayıtlı bir liste zaten var.');return}const details=p.due.map(d=>({...d,paid:true})),batch={id:id(),year:p.yr,institutionId:p.inst,date:new Date().toISOString().slice(0,10),details,totalGross:details.filter(d=>d.mode==='Nakdi').reduce((a,d)=>a+d.amount,0),totalNet:details.filter(d=>d.mode==='Nakdi').reduce((a,d)=>a+d.net,0),totalAyni:details.filter(d=>d.mode==='Ayni').reduce((a,d)=>a+d.amount,0)};db.batches.push(batch);await save();render();$('#calcResult').innerHTML=`<div class="callout green">Liste kaydedildi. Nakdi ve ayni çıktılarını aşağıdaki listeden görüntüleyebilirsiniz.</div><button class="btn" data-action="view-batch" data-id="${batch.id}">Kaydedilen listeyi görüntüle</button>`;bindPage()}
async function bindGlobal(){const root=$('#page');root.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(e.target.id==='csvFile')await importCsv(f);if(e.target.id==='tariffFile')await importTariffs(f);if(e.target.id==='backupFile')await restoreBackup(f);e.target.value=''})}
async function init(){nav();await load();await bindGlobal();render()}

function addStaff(){if(!db.institutions.length){toast('Önce kurum ekleyin.');return setPage('institutions')}const d=modal('Personel ekle','Kişisel kimlik bilgisi zorunlu değildir; T.C. kimlik numarasını yalnızca çıktı için gerekiyorsa girin.',`<div class="formgrid">${field('Ad soyad','name','Ad Soyad')}<div class="field"><label>Kurum</label><select name="institutionId" required>${db.institutions.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select></div>${field('Kadro unvanı','title','Örn. Hizmetli')}<div class="field"><label>Hizmet sınıfı</label><select name="serviceClass">${classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div>${field('T.C. kimlik numarası (isteğe bağlı)','nationalId','11 haneli numara','text')}<div class="field"><label>Durum</label><select name="active"><option value="true">Aktif</option><option value="false">Pasif</option></select></div></div><p class="hint">Bu bilgisayarın yerel veritabanında saklanır. Yedek dosyası oluşturulduğunda bu bilgi de yedeğe girer.</p>`);$('#modalSave').onclick=async e=>{e.preventDefault();const f=new FormData($('#modalForm')),tc=String(f.get('nationalId')||'').trim();if(!f.get('name').trim()||!f.get('title').trim())return;if(tc&&(!/^\d{11}$/.test(tc))){toast('T.C. kimlik numarası 11 rakam olmalıdır.');return}db.staff.push({id:id(),name:f.get('name').trim(),institutionId:f.get('institutionId'),title:f.get('title').trim(),serviceClass:f.get('serviceClass'),nationalId:tc,active:f.get('active')==='true'});await save();d.close();render();toast('Personel eklendi.')}}
async function importCsv(file){const rows=csvParse(await csvText(file));if(rows.length<2){toast('CSV dosyasında veri satırı yok.');return}const headers=rows[0].map(norm),find=(...names)=>names.map(x=>headers.indexOf(norm(x))).find(i=>i>=0),ix={name:find('Ad Soyad','Adı Soyadı','Ad Soyadi'),inst:find('Kurum','Okul','Kurum Adı'),title:find('Unvan','Kadro Unvanı','Ünvan'),cls:find('Hizmet Sınıfı','Sınıf'),tc:find('T.C. Kimlik No','TC Kimlik No','T.C.')};if([ix.name,ix.inst,ix.title,ix.cls].some(x=>x===undefined)){toast('CSV başlıklarını kontrol edin: Ad Soyad, Kurum, Unvan, Hizmet Sınıfı');return}let n=0;for(const r of rows.slice(1)){const name=(r[ix.name]||'').trim(),institution=(r[ix.inst]||'').trim(),title=(r[ix.title]||'').trim(),serviceClass=(r[ix.cls]||'').trim(),tc=ix.tc===undefined?'':(r[ix.tc]||'').trim();if(!name||!institution||!title)continue;let ins=db.institutions.find(x=>norm(x.name)===norm(institution));if(!ins){ins={id:id(),name:institution,type:'Okul'};db.institutions.push(ins)}if(db.staff.some(s=>norm(s.name)===norm(name)&&s.institutionId===ins.id&&norm(s.title)===norm(title)))continue;db.staff.push({id:id(),name,institutionId:ins.id,title,serviceClass:classes.includes(serviceClass)?serviceClass:'Diğer',nationalId:/^\d{11}$/.test(tc)?tc:'',active:true});n++}await save();render();toast(`${n} personel kaydı içe aktarıldı.`)}
async function saveBatch(){const p=window.pendingBatch;if(!p||!p.due.length){toast('Kaydedilecek ödeme kalemi yok.');return}if(p.due.some(d=>d.mode==='Nakdi')){const y=db.years.find(x=>Number(x.year)===p.yr);if(!y||String(y.incomeTax).trim()===''||String(y.stampTax).trim()===''){toast('Önce yıllık gelir ve damga vergisi oranlarını girip kaydedin.');return}}if(db.batches.some(b=>Number(b.year)===p.yr&&b.institutionId===p.inst)){toast('Bu kurum ve yıl için kayıtlı bir liste zaten var.');return}const cash=p.due.filter(d=>d.mode==='Nakdi'),gross=cash.reduce((a,d)=>a+d.amount,0),source=(db.years.find(x=>Number(x.year)===p.yr)||{}).source||`Hazine ve Maliye Bakanlığı ${p.yr} yılı Giyecek Yardımı Genelgesi`,cfg=db.documentSettings||{};const d=modal('Harcama talimatı bilgileri','Mevcut harcama talimatı şablonundaki üst alanları tamamlayın.',`<div class="formgrid">${field('Talimat tarihi','date', '', 'date',new Date().toISOString().slice(0,10))}${field('Talimat / sıra numarası','number','İsteğe bağlı')}${field('Hukuki dayanak','basis','Genelge / mevzuat', 'text',source)}${field('Konusu / niteliği','subject','Örn. 2026 yılı giyecek yardımı ödemesi','text',`${p.yr} yılı giyecek yardımı ödemesi`)}${field('Miktarı','quantity','Kişi sayısı veya adet','text',String(new Set(p.due.map(x=>x.staffId)).size+' kişi'))}${field('Gerçekleştirme süresi','period','Örn. 31.12.2026 tarihine kadar','text',String(p.yr))}<div class="field"><label>Gerçekleştirme usulü</label><select name="method"><option ${cash.length?'selected':''}>Nakdi</option><option ${cash.length?'':'selected'}>Ayni</option><option>Karışık</option></select></div>${field('Tutar / yaklaşık bedel (TL)','amount','', 'number',gross.toFixed(2))}${field('Kullanılabilir ödenek (TL)','appropriation','', 'number',gross.toFixed(2))}${field('Ödeneğin bütçe tertibi','budget','Bütçe kodu')}${field('Gerçekleştirme görevlileri','officers','Ad soyad','text',[cfg.proposedName,cfg.proposedTitle].filter(Boolean).join(' · '))}${field('Harcama yetkilisi','authority','Ad soyad','text',[cfg.authorityName,cfg.authorityTitle].filter(Boolean).join(' · '))}</div><p class="hint">Bütçe tertibi ve imza yetkilisi bilgilerini kurumunuzdaki güncel yetki ve ödenek kayıtlarına göre girin. Bu bilgiler sistem tarafından tahmin edilmez.</p>`);$('#modalSave').onclick=async e=>{e.preventDefault();const f=new FormData($('#modalForm')),details=p.due.map(x=>({...x,paid:true})),batch={id:id(),year:p.yr,institutionId:p.inst,date:f.get('date')||new Date().toISOString().slice(0,10),number:String(f.get('number')||''),details,totalGross:cash.reduce((a,x)=>a+x.amount,0),totalNet:cash.reduce((a,x)=>a+x.net,0),totalAyni:p.due.filter(x=>x.mode==='Ayni').reduce((a,x)=>a+x.amount,0),harcama:{basis:f.get('basis'),subject:f.get('subject'),quantity:f.get('quantity'),period:f.get('period'),method:f.get('method'),amount:Number(f.get('amount'))||0,appropriation:Number(f.get('appropriation'))||0,budget:f.get('budget'),officers:f.get('officers'),authority:f.get('authority')}};db.batches.push(batch);await save();d.close();render();toast('Harcama ve dağıtım listesi kaydedildi.');viewBatch(batch.id)}}
function viewBatch(key){const b=db.batches.find(x=>x.id===key);if(!b)return;const h=b.harcama||{};const d=modal(`Ödeme listesi · ${b.year}`,`${instName(b.institutionId)} · ${dateText(b.date)}`,`<div class="actions no-print"><button class="btn secondary" id="exportCash">Nakdi CSV indir</button><button class="btn secondary" id="exportAyni">Ayni CSV indir</button><button class="btn light" id="printReport">Talimat ve listeleri yazdır / PDF</button></div><div id="printArea"><section class="printPage"><h2>HARCAMA TALİMATI</h2><p>${esc(instName(b.institutionId))} · ${b.year} · ${dateText(b.date)} · Talimat no: ${esc(b.number||'—')}</p><table class="reporttable"><tbody>${[['Harcama Talebinde Bulunan Birim',instName(b.institutionId)],['Gerekçesi ve hukuki dayanağı',h.basis||'—'],['Konusu / nev’i / niteliği',h.subject||'—'],['Miktarı',h.quantity||'—'],['Gerçekleştirme süresi',h.period||'—'],['Gerçekleştirme usulü',h.method||'—'],['Tutarı veya yaklaşık bedeli',money(h.amount)],['Kullanılabilir ödenek tutarı',money(h.appropriation)],['Ödeneğin bütçe tertibi',h.budget||'—'],['Gerçekleştirme görevlileri',h.officers||'—'],['Harcama yetkilisi',h.authority||'—']].map(x=>`<tr><th>${esc(x[0])}</th><td>${esc(x[1])}</td></tr>`).join('')}</tbody></table></section>${['Nakdi','Ayni'].map(mode=>{const list=b.details.filter(x=>x.mode===mode);return `<section class="printPage"><h2>GİYECEK YARDIMI DAĞITIM LİSTESİ · ${mode.toLocaleUpperCase('tr')}</h2><p>${esc(instName(b.institutionId))} · ${b.year}</p><table class="reporttable"><thead><tr><th>Sıra</th><th>Adı Soyadı</th><th>Unvanı</th><th>T.C.</th><th>Giyecek adı</th><th>Tutarı</th></tr></thead><tbody>${list.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.staffName)}</td><td>${esc(x.title)}</td><td>${esc(db.staff.find(s=>s.id===x.staffId)?.nationalId||'')}</td><td>${esc(x.item)}</td><td>${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="6">Bu yardım türünde kayıt yok.</td></tr>'}</tbody></table><p class="reporttotal">${mode} toplamı: ${money(mode==='Nakdi'?b.totalGross:b.totalAyni)}</p></section>`}).join('')}</div><div class="callout">Resmî ödeme öncesinde tutarları, kesintileri, uygunluk durumunu ve imza bilgilerini kontrol edin.</div>`,'Kapat');$('#exportCash').onclick=()=>downloadCsv(b,'Nakdi');$('#exportAyni').onclick=()=>downloadCsv(b,'Ayni');$('#printReport').onclick=()=>window.print()}
