function viewBatch(key){const b=db.batches.find(x=>x.id===key);if(!b)return;const h=b.harcama||{},items=new Map();for(const x of b.details){const k=`${x.item}¦${x.mode}¦${Number(x.amount)/(Number(x.quantity)||1)}`;const r=items.get(k)||{item:x.item,mode:x.mode,unit:Number(x.amount)/(Number(x.quantity)||1),quantity:0,total:0};r.quantity+=Number(x.quantity)||1;r.total+=Number(x.amount)||0;items.set(k,r)}const people=new Map();for(const x of b.details){const r=people.get(x.staffId)||{name:x.staffName,title:x.title,nationalId:db.staff.find(s=>s.id===x.staffId)?.nationalId||'',details:[],total:0};r.details.push(x);r.total+=Number(x.amount)||0;people.set(x.staffId,r)}const moneyTotal=b.details.reduce((a,x)=>a+Number(x.amount||0),0);const d=modal(`Ödeme listesi · ${b.year}`,`${instName(b.institutionId)} · ${dateText(b.date)}`,`<div class="actions no-print"><button class="btn secondary" id="exportCash" type="button">Nakdi CSV indir</button><button class="btn secondary" id="exportAyni" type="button">Ayni CSV indir</button><button class="btn light" id="printReport" type="button">Excel şablonuna uygun PDF’yi yeniden kaydet</button></div><div id="printArea"><section class="printPage instructionPage"><h2>HARCAMA TALİMATI</h2><div class="instructionFrame"><div class="instructionTop"><b>Sayı: ${esc(b.number||'')}</b><span><b>Tarih:</b> ${dateText(b.date)}</span></div><div class="requestUnit"><b>Harcama Talebinde Bulunan Birim:</b><span>${esc(h.unit||instName(b.institutionId))}</span></div><div class="reasonTable"><div class="verticalLabel">Y A P I L A C A K&nbsp;&nbsp; H A R C A M A N I N</div><table class="reporttable"><tbody>${[['Gerekçesi ve hukuki dayanağı',h.basis],['Konusu / nev’i / niteliği',h.subject],['Miktarı',h.quantity],['Gerçekleştirme süresi',h.period],['Gerçekleştirme usulü',h.method],['Tutarı veya belirlenmiş yaklaşık bedeli',money(h.amount)],['Kullanılabilir ödenek tutarı',money(h.appropriation)],['Ödeneğin bütçe tertibi',h.budget],['Gerçekleştirme görevlileri',h.officers],['Harcama Yetkilisi',h.authority]].map(x=>`<tr><th>${esc(x[0])}</th><td>${esc(x[1]||'')}</td></tr>`).join('')}</tbody></table></div><div class="explanation"><b>AÇIKLAMALAR:</b><div class="explanationTitle">${esc(h.explanationTitle||'')}</div><div class="explanationBox">${esc(h.explanation||'')}</div></div><div class="approval">Yukarıda belirtilen harcamanın yaptırılması hususunu olurlarınıza arz ederim.<div class="approvalGrid"><div><div class="signHead">Teklif Eden Yetkilinin</div><p>İmzası :</p><p>Adı Soyadı : ${esc(h.proposedName||'')}</p><p>Unvanı : ${esc(h.proposedTitle||'')}</p></div><div><div class="signHead">O L U R</div><p>İmzası :</p><p>Adı Soyadı : ${esc(h.authorityName||'')}</p><p>Unvanı : ${esc(h.authorityTitle||'')}</p></div></div></div></div></section><section class="printPage distributionPage"><div class="distributionDate">Tarih: ${dateText(b.date)}</div><h2>${esc(instName(b.institutionId).toLocaleUpperCase('tr'))} ${b.year} GİYİM YARDIMI ÖDEMESİ</h2><table class="reporttable peopleTable"><thead><tr><th>Sıra No</th><th>Adı Soyadı</th><th>Unvanı</th><th>T.C.</th><th>Giyecek Adı</th><th>Tutarı</th></tr></thead><tbody>${[...people.values()].map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name)}</td><td>${esc(x.title)}</td><td>${esc(x.nationalId)}</td><td>${x.details.map(z=>`${Number(z.quantity)||1} ADET ${esc(z.item)}${z.mode==='Ayni'?' (AYNİ)':''}`).join('<br>')}</td><td>${money(x.total)}</td></tr>`).join('')}</tbody></table><table class="reporttable summaryTable"><thead><tr><th>GİYİM ADI</th><th>BİRİM FİYATI</th><th>ADET</th><th>TOPLAMI</th></tr></thead><tbody>${[...items.values()].map(x=>`<tr><td>${esc(x.item)}${x.mode==='Ayni'?' (Ayni)':''}</td><td>${money(x.unit)}</td><td>${x.quantity}</td><td>${money(x.total)}</td></tr>`).join('')}<tr class="grandTotal"><th colspan="3">TOPLAM</th><th>${money(moneyTotal)}</th></tr></tbody></table><div class="distributionSignatures"><div>${esc(h.proposedName||'')}<br>${esc(h.proposedTitle||'')}</div><div>${esc(h.authorityName||'')}<br>${esc(h.authorityTitle||'')}</div></div></section></div><div class="callout no-print">PDF’de Excel şablonundaki tam harcama talimatı, kişi bazlı dağıtım, giyecek bazında adet/birim fiyat/toplam ve imza alanları bulunur.</div>`,'Kapat');$('#exportCash').onclick=()=>downloadCsv(b,'Nakdi');$('#exportAyni').onclick=()=>downloadCsv(b,'Ayni');$('#printReport').onclick=()=>window.chrome?.webview?.postMessage({type:'exportPdf',year:b.year,institution:instName(b.institutionId)})}

pages.signers='İmza ve Talimat Ayarları';
function signaturesPage(){const c=db.documentSettings||{};return `<div class="card"><div class="cardhead"><div><h2>İmza ve harcama talimatı varsayılanları</h2><p>Buraya kaydettiğiniz bilgiler yeni harcama talimatlarına otomatik aktarılır. Talimat penceresinde işlem bazında değiştirilebilir.</p></div></div><div class="formgrid"><div class="field"><label>Gerçekleştirme görevlisi · Adı soyadı</label><input id="cfgProposedName" value="${esc(c.proposedName||'')}" placeholder="Adı Soyadı"></div><div class="field"><label>Gerçekleştirme görevlisi · Unvanı</label><input id="cfgProposedTitle" value="${esc(c.proposedTitle||'')}" placeholder="Görev unvanı"></div><div class="field"><label>Harcama yetkilisi · Adı soyadı</label><input id="cfgAuthorityName" value="${esc(c.authorityName||'')}" placeholder="Adı Soyadı"></div><div class="field"><label>Harcama yetkilisi · Unvanı</label><input id="cfgAuthorityTitle" value="${esc(c.authorityTitle||'')}" placeholder="Görev unvanı"></div><div class="field wide"><label>Gerekçesi ve hukuki dayanağı</label><textarea id="cfgBasis" rows="4" placeholder="Harcama Talimatı sayfasındaki ilgili hücreye aktarılacak varsayılan metin">${esc(c.basis||'')}</textarea></div></div><button class="btn" id="saveDocSettings" type="button">İmza ve talimat bilgilerini kaydet</button></div><div class="callout green">Kaydedilen gerekçe, sonraki ödeme talimatlarında otomatik gelir. Bu menüden yapılan değişiklikler geçmişte oluşturulmuş talimatları değiştirmez.</div>`}
async function saveDocSettings(){db.documentSettings={proposedName:$('#cfgProposedName').value.trim(),proposedTitle:$('#cfgProposedTitle').value.trim(),authorityName:$('#cfgAuthorityName').value.trim(),authorityTitle:$('#cfgAuthorityTitle').value.trim(),basis:$('#cfgBasis').value.trim()};await save();toast('İmza ve talimat varsayılanları kaydedildi.')}
function render(){const root=$('#page');if(page==='overview')root.innerHTML=overview();if(page==='institutions')root.innerHTML=institutionsPage();if(page==='staff')root.innerHTML=staffPage();if(page==='signers')root.innerHTML=signaturesPage();if(page==='tariffs')root.innerHTML=yearCatalogPage();if(page==='payments')root.innerHTML=manualPaymentsPage();if(page==='payments')drawRoster();bindPage();const saveCfg=$('#saveDocSettings');if(saveCfg)saveCfg.onclick=saveDocSettings}async function loadPdfJs(){if(window.pdfjsLib)return window.pdfjsLib;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('PDF okuma bileşeni yüklenemedi. İnternet bağlantınızı kontrol edin.'));document.head.appendChild(script)});if(!window.pdfjsLib)throw new Error('PDF okuma bileşeni başlatılamadı.');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';return window.pdfjsLib}
function extractPriceRows(textContent){const lines=new Map();for(const item of textContent.items||[]){const value=String(item.str||'').trim();if(!value)continue;const y=Math.round(Number(item.transform?.[5]||0)*2)/2;const line=lines.get(y)||[];line.push({x:Number(item.transform?.[4]||0),value});lines.set(y,line)}const rows=[];for(const [,parts] of [...lines.entries()].sort((a,b)=>b[0]-a[0])){const line=parts.sort((a,b)=>a.x-b.x).map(x=>x.value).join(' ').replace(/\\s+/g,' ').trim();const match=line.match(/(?:^|\\s)(\\d{1,2})\\s+(.+?)\\s+([\\d.]+,\\d{2})\\s*$/);if(!match)continue;const rowNumber=Number(match[1]),amount=Number(match[3].replace(/\\./g,'').replace(',','.'));if(rowNumber>=1&&rowNumber<=38&&Number.isFinite(amount)&&amount>0)rows.push({rowNumber,amount,rawItem:match[2].trim()})}const byNumber=new Map();for(const row of rows){if(byNumber.has(row.rowNumber))throw new Error('PDF içinde yinelenen sıra numarası bulundu: '+row.rowNumber);byNumber.set(row.rowNumber,row)}return [...byNumber.values()].sort((a,b)=>a.rowNumber-b.rowNumber)}
async function importOfficialTariffs(){const button=$('[data-action="import-tariff-pdf"]');if(button)button.disabled=true;try{if(Number(activeYear)!==2026)throw new Error('Bu otomatik kaynak şu anda 2026 yılı resmî PDF listesi için tanımlı. Seçili yılın fiyatları değiştirilmedi.');toast('Hazine ve Maliye Bakanlığının resmî PDF listesi indiriliyor…');const response=await fetch('/api/official-tariffs/2026',{cache:'no-store'});if(!response.ok)throw new Error('Resmî PDF indirilemedi (HTTP '+response.status+'). Sunucuyu yeniden başlatıp tekrar deneyin.');const bytes=await response.arrayBuffer();if(bytes.byteLength<5000)throw new Error('Bakanlıktan gelen dosya beklenen PDF boyutunda değil.');const pdfjs=await loadPdfJs();const pdf=await pdfjs.getDocument({data:new Uint8Array(bytes)}).promise;if(pdf.numPages!==2)throw new Error('Resmî PDF’de beklenen 2 ek sayfası bulunamadı. Hiçbir fiyat değiştirilmedi.');const sheets=[];for(let pageNo=1;pageNo<=2;pageNo++){const page=await pdf.getPage(pageNo),content=await page.getTextContent(),text=(content.items||[]).map(x=>x.str||'').join(' ');if(!/2026/.test(text))throw new Error(pageNo+'. sayfada 2026 yılı doğrulanamadı.');if(pageNo===1&&!/AYN[Iİ].{0,30}GİYECEK|AYN[Iİ].{0,30}YARDIM/i.test(text))throw new Error('PDF’nin ilk sayfası Ek-1 (ayni) listesi olarak doğrulanamadı.');if(pageNo===2&&!/NAKD[Iİ].{0,30}GİYECEK|NAKD[Iİ].{0,30}YARDIM/i.test(text))throw new Error('PDF’nin ikinci sayfası Ek-2 (nakdi) listesi olarak doğrulanamadı.');const rows=extractPriceRows(content);if(rows.length!==38||rows.some((r,i)=>r.rowNumber!==i+1))throw new Error((pageNo===1?'Ek-1':'Ek-2')+' listesinde 38 fiyat satırının tamamı okunamadı ('+rows.length+'/38). Mevcut fiyatlar korundu.');const mode=pageNo===1?'Ayni':'Nakdi';sheets.push({year:2026,mode,fileName:'Hazine ve Maliye Bakanlığı 2026 Giyecek Yardımı Genelgesi · '+(mode==='Ayni'?'Ek-1':'Ek-2'),rows:rows.map(r=>({rowNumber:r.rowNumber,item:prices2026[r.rowNumber-1][0],amount:r.amount})),warnings:[]})}showPdfPricePreview({sheets,errors:[]})}catch(error){modal('Bakanlık fiyat listesi alınamadı',String(error?.message||error),'<div class="callout">Güvenlik kontrolü nedeniyle hiçbir fiyat kaydedilmedi. Mevcut listeniz korunmuştur.</div>','Kapat')}finally{if(button)button.disabled=false}}
function showPdfPricePreview(result){const sheets=result?.sheets||[],errors=[...(result?.errors||[])],years=new Set(sheets.map(x=>Number(x.year)));if(!sheets.length){modal('PDF okunamadı',errors.join(' · ')||'PDF içinde fiyat listesi bulunamadı.','<div class="callout">Bakanlığın metin içeren Ek-1 veya Ek-2 fiyat listesi PDF dosyasını seçin. Taranmış/görüntü PDF dosyaları otomatik okunamıyor.</div>','Kapat');return}if(years.size!==1)errors.push('Seçilen PDF’lerde tek bir fiyat yılı bulunmalıdır.');const allRows=sheets.flatMap(x=>x.rows||[]);for(const sh of sheets){if((sh.rows||[]).length<30)errors.push(`${sh.fileName} · ${sh.mode}: yalnızca ${(sh.rows||[]).length} satır okundu; eksik tablo kaydedilmeyecek.`);if(sh.warnings?.length)errors.push(`${sh.fileName}: ${sh.warnings.join(' ')}`);const seen=new Set();for(const row of sh.rows||[]){const key=String(row.item||'').trim().toLocaleLowerCase('tr');if(seen.has(key))errors.push(`${sh.mode} listesinde yinelenen giyecek adı: ${row.item}`);seen.add(key);if(!key||!Number.isFinite(Number(row.amount))||Number(row.amount)<=0)errors.push(`${sh.mode} listesinde geçersiz satır var.`)}}if(!['Ayni','Nakdi'].includes(sheets[0].mode)||sheets.some(x=>!['Ayni','Nakdi'].includes(x.mode)))errors.push('PDF türü Ayni veya Nakdi olarak belirlenemedi.');const uniqueErrors=[...new Set(errors)],year=years.values().next().value;const body=`<div class="callout green">PDF’deki liste otomatik okundu. Her dosya için yılı, yardım türünü, satır sayısını ve tutarları gözden geçirin. Seçmediğiniz yardım türünün fiyatları değiştirilmez.</div>${uniqueErrors.length?`<div class="callout">${uniqueErrors.map(esc).join('<br>')}</div>`:''}<div class="pdfImportSheets">${sheets.map(sh=>`<div class="card"><div class="cardhead"><div><h3>${esc(sh.year)} · ${esc(sh.mode==='Ayni'?'Ayni':'Nakdi')} birim fiyatlar</h3><p>${esc(sh.fileName)} · ${sh.rows.length} satır</p></div></div><div class="tablewrap"><table><thead><tr><th>Sıra</th><th>Giyecek kalemi</th><th>Birim fiyat</th></tr></thead><tbody>${sh.rows.map(r=>`<tr><td>${r.rowNumber}</td><td>${esc(r.item)}</td><td class="money">${money(r.amount)}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}</div><p class="hint">PDF’de metin katmanı varsa aktarım yapılır. Hatalı/eksik okuma tespitinde kaydetme kapatılır. Resmî ödeme öncesi önizleme değerlerini kontrol edin.</p>`;const d=modal('Bakanlık fiyat listesi · Önizleme',`${sheets.length} liste bulundu · ${allRows.length} fiyat satırı`,body,'Fiyatları içe aktar');const saveButton=$('#modalSave');saveButton.disabled=uniqueErrors.length>0;saveButton.title=uniqueErrors.length?'Hatalı/eksik liste düzeltilmeden içe aktarılamaz.':'';saveButton.onclick=async e=>{e.preventDefault();if(uniqueErrors.length)return;const modes=new Set(sheets.map(x=>x.mode)),year=Number(sheets[0].year);if(db.tariffs.some(t=>Number(t.year)===year&&modes.has(t.mode))&&!confirm(`${year} yılının seçilen yardım türlerindeki mevcut fiyatları PDF’den okunanlarla değiştirilsin mi?`))return;db.tariffs=db.tariffs.filter(t=>!(Number(t.year)===year&&modes.has(t.mode)));for(const sh of sheets)for(const row of sh.rows)db.tariffs.push({id:id(),year,item:row.item,mode:sh.mode,amount:Number(row.amount),years:0,source:`${sh.fileName} · Bakanlık PDF içe aktarma`});let y=db.years.find(x=>Number(x.year)===year);if(!y){y={year,incomeTax:'',stampTax:''};db.years.push(y)}y.source=sheets.map(x=>x.fileName).join(' + ');activeYear=year;await save();d.close();render();toast(`${allRows.length} fiyat satırı ${year} yılına aktarıldı.`)}}
